This pre-validates malformed percent-escapes, then uses `urllib.parse.unquote_plus` (Python docs: docs.python.org/3/library/urllib.parse.html#urllib.parse.unquote_plus) to decode plus and percent sequences.

```python
from urllib.parse import unquote_plus

_HEX = set('0123456789abcdefABCDEF')

def _validate(s: str) -> None:
    i = 0
    while i < len(s):
        if s[i] == '%':
            if i + 2 >= len(s) or s[i+1] not in _HEX or s[i+2] not in _HEX:
                raise ValueError('malformed percent-escape')
            i += 3
        else:
            i += 1

def parse_query(qs: str) -> dict:
    result = {}
    for pair in qs.split('&'):
        if pair == '':
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        _validate(key)
        _validate(value)
        decoded_key = unquote_plus(key)
        decoded_value = unquote_plus(value)
        result.setdefault(decoded_key, []).append(decoded_value)
    return result
```

