import urllib.parse

def _decode(s: str) -> str:
    s = s.replace('+', ' ')
    # Check for malformed % escapes (must be % followed by 2 hex digits)
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '%':
            if i + 2 >= n:
                raise ValueError('malformed percent-escape')
            h = s[i+1:i+3]
            if not all(c in '0123456789abcdefABCDEF' for c in h):
                raise ValueError('malformed percent-escape')
            i += 3
        else:
            i += 1
    try:
        return urllib.parse.unquote(s, errors='strict')
    except UnicodeDecodeError as e:
        raise ValueError('malformed percent-escape') from e

def parse_query(qs: str) -> dict:
    result = {}
    for pair in qs.split('&'):
        if not pair:
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        decoded_key = _decode(key)
        decoded_value = _decode(value)
        result.setdefault(decoded_key, []).append(decoded_value)
    return result
