import urllib.parse

def _decode(s: str) -> str:
    # Validate percent-escapes: each '%' must be followed by two hex digits.
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '%':
            if i + 2 >= n or not all(c in '0123456789abcdefABCDEF' for c in s[i+1:i+3]):
                raise ValueError('malformed percent-escape')
            i += 3
        else:
            i += 1
    # Decode '+' as space and valid percent-escapes. Invalid UTF-8 byte
    # sequences are replaced rather than treated as malformed escapes.
    return urllib.parse.unquote_plus(s, errors='replace')

def parse_query(qs: str) -> dict:
    result = {}
    for pair in qs.split('&'):
        if not pair:
            continue
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key, value = pair, ''
        decoded_key = _decode(key)
        decoded_value = _decode(value)
        result.setdefault(decoded_key, []).append(decoded_value)
    return result
```

